{"summary":"实现单请求仓库盘点服务：取消优先清空请求并仍更新按钮历史；按钮上升沿或已有Pending形成请求；服务可用且不忙时派发并清Pending，否则保留Pending；RequestLamp始终等于Pending。","code":"FUNCTION_BLOCK FB_InventoryRequest
VAR_INPUT
    RequestBtn : BOOL;
    ServiceReady : BOOL;
    Busy : BOOL;
    Cancel : BOOL;
END_VAR
VAR_OUTPUT
    Pending : BOOL := FALSE;
    RequestLamp : BOOL := FALSE;
    Dispatched : BOOL := FALSE;
END_VAR
VAR
    PrevCall : BOOL := FALSE;
    rise : BOOL;
    request : BOOL;
    canServe : BOOL;
END_VAR

rise := RequestBtn AND NOT PrevCall;
request := Pending OR rise;
canServe := ServiceReady AND NOT Busy;

IF Cancel THEN
    Pending := FALSE;
    Dispatched := FALSE;
ELSIF request AND canServe THEN
    Pending := FALSE;
    Dispatched := TRUE;
ELSE
    Pending := request;
    Dispatched := FALSE;
END_IF;

RequestLamp := Pending;
PrevCall := RequestBtn;
END_FUNCTION_BLOCK"}

